INSERT INTO public.parking_lot_survey_facts (
  lot_id, source_id, source_record_no, general_spaces, other_space_type, operation_category, operating_hours_text, management_type, resident_staff_count, control_system_linked, parking_portal_linked, display_installation_status, display_network_type, display_use_status, entrance_count, exit_count, entrance_exit_shared, existing_sensor_status, sensor_manufacturer, sensor_use_status, control_manufacturer, utilization_band, peak_period, primary_users, user_notes, new_sensor_target_count, gateway_target_count, display_development_possible, portal_link_possible, power_supply_status, wired_network_status, windows_update_status, priority_rank, priority_score, priority_note, source_pages, raw_survey_data
)
SELECT
  lot.id,
  (SELECT id FROM public.survey_data_sources WHERE source_code = 'JEJU_PAID_PARKING_2025_12'),
  survey_rows.source_record_no, survey_rows.general_spaces, survey_rows.other_space_type, survey_rows.operation_category, survey_rows.operating_hours_text, survey_rows.management_type, survey_rows.resident_staff_count, survey_rows.control_system_linked, survey_rows.parking_portal_linked, survey_rows.display_installation_status, survey_rows.display_network_type, survey_rows.display_use_status, survey_rows.entrance_count, survey_rows.exit_count, survey_rows.entrance_exit_shared, survey_rows.existing_sensor_status, survey_rows.sensor_manufacturer, survey_rows.sensor_use_status, survey_rows.control_manufacturer, survey_rows.utilization_band, survey_rows.peak_period, survey_rows.primary_users, survey_rows.user_notes, survey_rows.new_sensor_target_count, survey_rows.gateway_target_count, survey_rows.display_development_possible, survey_rows.portal_link_possible, survey_rows.power_supply_status, survey_rows.wired_network_status, survey_rows.windows_update_status, survey_rows.priority_rank, survey_rows.priority_score, survey_rows.priority_note, survey_rows.source_pages, survey_rows.raw_survey_data
FROM survey_rows
JOIN public.parking_lots lot ON lot.code = survey_rows.lot_code;

DO $$
DECLARE
  actual jsonb;
BEGIN
  SELECT jsonb_build_object(
    'record_count', count(*),
    'total_spaces', sum(total_spaces),
    'disabled_spaces', sum(disabled_spaces),
    'ev_spaces', sum(ev_spaces),
    'compact_spaces', sum(compact_spaces),
    'pregnant_spaces', sum(pregnant_spaces),
    'other_spaces', sum(other_spaces)
  ) INTO actual
  FROM public.parking_lots;

  IF actual <> '{"record_count":112,"total_spaces":6380,"disabled_spaces":287,"ev_spaces":161,"compact_spaces":510,"pregnant_spaces":10,"other_spaces":54}'::jsonb THEN
    RAISE EXCEPTION 'Jeju survey parking-lot validation failed: %', actual;
  END IF;

  IF (SELECT count(*) FROM public.parking_lot_survey_facts) <> 112 THEN
    RAISE EXCEPTION 'Jeju survey facts must contain exactly 112 rows';
  END IF;
  IF (SELECT sum(general_spaces) FROM public.parking_lot_survey_facts) <> 5358 THEN
    RAISE EXCEPTION 'Jeju survey general-space total must equal 5,358';
  END IF;
  IF (SELECT sum(new_sensor_target_count) FROM public.parking_lot_survey_facts) <> 3857 THEN
    RAISE EXCEPTION 'Jeju survey sensor target total must equal 3,857';
  END IF;
  IF (SELECT sum(gateway_target_count) FROM public.parking_lot_survey_facts) <> 99 THEN
    RAISE EXCEPTION 'Jeju survey detail-row gateway total must equal 99';
  END IF;
END;
$$;
